import{_ as n,o as t,c as r,a3 as i}from"./chunks/framework.BlfGB29P.js";const c=JSON.parse('{"title":"ATLAS im Home-Assistant-Frontend","description":"","frontmatter":{},"headers":[],"relativePath":"projects/atlas/frontend.md","filePath":"projects/atlas/frontend.md","lastUpdated":1792861021000}'),a={name:"projects/atlas/frontend.md"};function s(o,e,d,l,u,g){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="atlas-im-home-assistant-frontend" tabindex="-1">ATLAS im Home-Assistant-Frontend <a class="header-anchor" href="#atlas-im-home-assistant-frontend" aria-label="Permalink to &quot;ATLAS im Home-Assistant-Frontend&quot;">​</a></h1><p>Ab <strong>0.1.299</strong> enthält ATLAS die optionale Integration <strong>ATLAS Runtime</strong>. Sie registriert einen eigenen Seitenleisteneintrag für HA-Administratoren. Darin öffnen sich Plugin Hub, Expert Card Editor und Administration der vorhandenen ATLAS-Laufzeit. Die Oberfläche folgt der HA-Sprache DE/EN/FR und der hellen oder dunklen Darstellung.</p><h2 id="voraussetzungen-und-datenerhalt" tabindex="-1">Voraussetzungen und Datenerhalt <a class="header-anchor" href="#voraussetzungen-und-datenerhalt" aria-label="Permalink to &quot;Voraussetzungen und Datenerhalt&quot;">​</a></h2><p>Stand 16.10.2026: <strong>App 0.1.312</strong>, <strong>Integration 0.1.306</strong>. Die Versionsnummern sind unabhängig. Die unten genannten Einführungs- und Prüfversionen sind keine Aufforderung, eine vorhandene neuere App zurückzusetzen. Vollständiger HAOS-Restore und ein bewusster Adresswechsel sind im <a href="./../atlas-plugins/file-studio">Sicherungsleitfaden</a> beschrieben; browserlokale Daten brauchen weiterhin einen eigenen Export.</p><p>ATLAS muss bereits als App/Add-on, Docker-Container oder <a href="/projects/atlas/linux">Linux/systemd-Dienst</a> laufen. HACS installiert die HA-Integration; der Node-Server und externe Plugins bleiben in ihrer Laufzeit. Der bestehende Add-on-Ingress-Eintrag wird nicht ersetzt.</p><p>Sichere HA vor der Installation. Exportiere bestehende ATLAS-Projekte und Administrationseinstellungen zusätzlich in ATLAS. Behalte die bisherige Browseradresse der Laufzeit bei: Browserprojekte, Cookies und verschlüsselte Einstellungen sind an Adresse beziehungsweise Installationsidentität gebunden. Ein Wechsel von Hostname, Schema oder Port ist keine automatische Datenmigration.</p><p>Browser können den Speicher einer extern eingebetteten Laufzeit zusätzlich von ihrem separat geöffneten Speicher trennen. Falls vorhandene Projekte oder verschlüsselte Einstellungen im Panel fehlen, öffne die bisherige Adresse über <strong>Separat öffnen</strong> und exportiere sie dort; die Integration verschiebt oder löscht diese Daten nicht. <a href="https://privacysandbox.google.com/cookies/storage-partitioning" target="_blank" rel="noreferrer">Hintergrund zur Speichertrennung</a>.</p><h2 id="installation-uber-hacs" tabindex="-1">Installation über HACS <a class="header-anchor" href="#installation-uber-hacs" aria-label="Permalink to &quot;Installation über HACS&quot;">​</a></h2><ol><li>Öffne HACS und seine benutzerdefinierten Repositories.</li><li>Füge <code>https://github.com/rockbaer2007/atlas</code> mit Typ <strong>Integration</strong> hinzu.</li><li>Lade <strong>ATLAS Runtime</strong> herunter und starte Home Assistant neu.</li><li>Öffne <strong>Einstellungen → Geräte &amp; Dienste → Integration hinzufügen → ATLAS Runtime</strong>.</li><li>Trage die im Browser erreichbare Basisadresse der bisherigen Laufzeit ein, zum Beispiel <code>http://atlas-server:4176/</code> oder <code>https://atlas.example.org/atlas/</code>.</li></ol><p>Keine HA-Tokens oder Provider-Schlüssel werden in dieser Integration abgefragt. Die HA-Verbindung bleibt in der ATLAS-Administration. Der Panelcode überträgt keine HA-Authentifizierung oder Entitätsdaten an das eingebettete Fenster. Normale HA-Zustandsupdates laden dieses Fenster nicht erneut.</p><p>Dies ist ein benutzerdefiniertes HACS-Repository; eine Aufnahme in den allgemeinen HACS-Katalog wird nicht behauptet. Der Repositorytyp ist <strong>Integration</strong>, nicht Dashboard. Exportierte HACS-Kartenpakete sind ein separater Workflow.</p><h3 id="hacs-meldet-„unknown-error" tabindex="-1">HACS meldet „Unknown error“ <a class="header-anchor" href="#hacs-meldet-„unknown-error" aria-label="Permalink to &quot;HACS meldet „Unknown error“&quot;">​</a></h3><p>Prüfe den zugehörigen Eintrag unter <strong>Einstellungen → System → Protokolle</strong>. Beim ersten Proxmox-Download wurde in <code>hacs_repository_download</code> der Fehler <code>AttributeError: &#39;NoneType&#39; object has no attribute &#39;data&#39;</code> beobachtet: HACS fand seinen Repository-Eintrag nicht, noch bevor der Paketdownload begann. Lade die HACS-Seite neu, öffne <strong>ATLAS Runtime</strong> erneut und wiederhole den Download. Im geprüften Fall erschien danach <strong>Ausstehender Neustart</strong>. Diese Meldung bestätigt den Download; die Einrichtung nach dem HA-Neustart ist ein weiterer Schritt. Andere „Unknown error“-Ursachen benötigen den jeweiligen Protokolleintrag.</p><h2 id="gemeinsame-plugin-verwaltung-ab-0-1-300" tabindex="-1">Gemeinsame Plugin-Verwaltung ab 0.1.300 <a class="header-anchor" href="#gemeinsame-plugin-verwaltung-ab-0-1-300" aria-label="Permalink to &quot;Gemeinsame Plugin-Verwaltung ab 0.1.300&quot;">​</a></h2><p>App/Ingress und Runtime können die Repository-Liste, importierte Plugin-Metadaten und Aktivierungszustände im selben ATLAS-Server speichern. Aktualisiere zuerst die <strong>ATLAS-App/Laufzeit</strong> auf 0.1.300; allein ein HACS-Update genügt dafür nicht.</p><ol><li>Öffne den bisherigen <strong>ATLAS-App-Zugang</strong>, in dem alle Plugins vorhanden sind.</li><li>Öffne Administration → Plugin-Manager → <strong>Gemeinsame Plugin-Verwaltung</strong>.</li><li>Wähle <strong>Lokalen Stand übernehmen</strong> und prüfe Repository-, Plugin- und Aktivierungszahlen sowie angezeigte Konflikte.</li><li>Standardmäßig bleiben bei Konflikten die Serverwerte erhalten. Wähle den lokalen Stand nur, wenn dessen Werte bewusst übernommen werden sollen.</li><li>Klicke <strong>Gesichert übernehmen</strong>. Ein Download sichert die Plugin-Metadaten; der Server sichert zusätzlich den bisherigen Stand und die Übernahmedaten, bevor er atomar speichert.</li><li>Öffne die Runtime erneut oder nutze <strong>Serverstand laden</strong>. Weitere Änderungen werden gemeinsam gespeichert; offene Administrationen prüfen den Stand alle 15 Sekunden. Gleichzeitige Änderungen mit veraltetem Stand werden abgewiesen.</li></ol><p>Eine leere Übernahme entfernt keine vorhandenen Servereinträge. Bis zur ersten bestätigten Übernahme bleibt die bisherige lokale Verwaltung gültig. Die alten Browserdaten werden durch die Übernahme nicht gelöscht. Nicht gespeicherte Änderungen erhalten eine eigene lokale Wiederherstellungskopie und können erneut zur Übernahme geprüft werden. <strong>Sicherung prüfen</strong> liest einen Metadatenexport oder eine Server-Sicherung mit Vorschau; die Übernahme führt Einträge zusammen.</p><p>Der Serverstand liegt unter <code>ATLAS_PLUGIN_DATA_ROOT/.management/state.json</code>, die Sicherungen unter <code>.management/backups/</code>. Beim App/Add-on und in Docker liegt dies im dauerhaften Plugin-Datenverzeichnis. Sichere dieses Verzeichnis mit der Laufzeit. Es werden keine Pakete automatisch installiert oder entfernt. HA-Tokens, Provider-Schlüssel, Dateiberechtigungen, Editor-Projekte und eigene Einstellungen externer Plugins bleiben außerhalb dieser Übernahme.</p><h2 id="gemeinsame-editor-projekte-ab-0-1-301" tabindex="-1">Gemeinsame Editor-Projekte ab 0.1.301 <a class="header-anchor" href="#gemeinsame-editor-projekte-ab-0-1-301" aria-label="Permalink to &quot;Gemeinsame Editor-Projekte ab 0.1.301&quot;">​</a></h2><p>Aktualisiere die ATLAS-App/Laufzeit auf <strong>0.1.301</strong>. Öffne zuerst den bisherigen App-Editor mit deinem vorhandenen Projekt. Unter <strong>Gemeinsame Editor-Projekte</strong> wähle <strong>Neues Serverprojekt → Prüfen und speichern</strong>. Prüfe Name und Feldanzahl, dann <strong>Gesichert übernehmen</strong>. Zum Übernehmen eines weiteren lokalen Projekts wähle erneut <strong>Neues Serverprojekt</strong>; gleiche Namen sind erlaubt und ersetzen keine anderen Projekte automatisch.</p><p>In der Runtime: <strong>Projektliste laden</strong>, Projekt auswählen, <strong>Öffnen prüfen</strong>, Vorschau prüfen und <strong>Gesichert übernehmen</strong>. Gespeichert werden Expert-Felder mit ihren Card-Konfigurationen, Projektname, Scriptname, Fläche und Rastergröße. Änderungen werden ausdrücklich über <strong>Prüfen und speichern</strong> gespeichert. Gleichzeitige Änderungen desselben Projekts werden per Versionsprüfung erkannt. Die Arbeitsfläche wird nicht automatisch aus einem anderen Browser ersetzt.</p><p>Vor dem Öffnen oder Speichern wird die aktuelle Arbeitsfläche serverseitig unter <code>ATLAS_PLUGIN_DATA_ROOT/.projects/workspaces/</code> und als Download gesichert. Vorherige Serverstände liegen unter <code>.projects/backups/</code>, benannte Projekte in <code>.projects/projects.json</code>. Sichere das dauerhafte Plugin-Datenverzeichnis mit. <strong>Sicherung prüfen</strong> öffnet einen Arbeitsflächen-Backup-Download mit Vorschau. <strong>Lokalen Entwurf prüfen</strong> stellt einen ungespeicherten gemeinsamen Entwurf aus diesem Browser wieder bereit; nach einem Neuladen wird er nicht automatisch geöffnet.</p><p>Der ursprüngliche lokale Projektstand bleibt im alten Browserspeicher erhalten. Gemeinsame Arbeitsflächen erhalten einen separaten lokalen Entwurf. Einstellungen, HA-Zugangsdaten, Plugin-Verwaltung, Palettenfavoriten und externe Plugin-Projekte werden nicht mitübertragen. Eine beschädigte Serverdatei wird nicht ersetzt. Grenzen: 100 Projekte, 4 MiB je Projekt und 64 MiB für die Projektdatei.</p><h2 id="manuelle-installation-und-updates" tabindex="-1">Manuelle Installation und Updates <a class="header-anchor" href="#manuelle-installation-und-updates" aria-label="Permalink to &quot;Manuelle Installation und Updates&quot;">​</a></h2><p>Kopiere ausschließlich <code>custom_components/atlas_frontend</code> aus dem Repository nach <code>/config/custom_components/atlas_frontend</code>. Sichere einen vorhandenen Ordner vor dem Austausch; andere Komponenten bleiben erhalten. Starte HA neu und füge die Integration wie oben hinzu. <code>manifest.json</code> enthält die Version.</p><p>Bei Updates über HACS aktualisiere nur diese Integration und starte HA neu. Die Laufzeitadresse bleibt im HA-Konfigurationseintrag erhalten. Der ATLAS-Server wird unabhängig über seinen vorhandenen Installationsweg aktualisiert. <strong>Konfigurieren</strong> an der Integration ändert die Adresse; exportiere ATLAS-Daten vor einem bewussten Wechsel. Entfernen der Integration entfernt ihren eigenen Panelzugang, nicht die ATLAS-Laufzeit, ihre Plugins oder ihre Projekte.</p><p>Ab Integration <strong>0.1.306</strong> werden unbekannte Konfigurationsformate beim Migrationsversuch abgewiesen, ohne den Eintrag umzuschreiben. Die bisherige Version <strong>1.1</strong> des Konfigurationsformats bleibt unverändert; die Paketversion ist davon unabhängig. Eine Rückkehr zu einer älteren Integration ist nur bei kompatiblem Datenformat geprüft. Sichere vor Updates HA-Konfiguration und ATLAS-Daten; bei einer späteren Formatänderung gehört die passende Datensicherung zur Wiederherstellung. Eine ungültige gespeicherte Laufzeitadresse wird als Einrichtungsfehler gemeldet und kann über <strong>Konfigurieren</strong> korrigiert werden.</p><h2 id="http-https-und-einbettung" tabindex="-1">HTTP, HTTPS und Einbettung <a class="header-anchor" href="#http-https-und-einbettung" aria-label="Permalink to &quot;HTTP, HTTPS und Einbettung&quot;">​</a></h2><p>Wenn HA über HTTPS erreichbar ist, benötigt die eingebettete Laufzeit ebenfalls HTTPS. Ein HTTP-Ziel zeigt stattdessen einen Hinweis und <strong>Separat öffnen</strong>. Die Basisadresse darf keine Zugangsdaten, Abfrageparameter oder Fragmente enthalten. Port 80 ist zulässig. Reverse-Proxy-Präfixe bleiben erhalten.</p><p>Ein Reverse Proxy muss die ATLAS-Unterpfade korrekt weiterleiten und die Einbettung von der HA-Origin erlauben. Bei einer leeren Ansicht prüfe zuerst <strong>Separat öffnen</strong>, Erreichbarkeit, Proxy-Weiterleitung und Frame-Schutzheader. Eine automatisch ermittelte oder dauerhaft gespeicherte Ingress-Sitzungsadresse ist nicht Teil dieser Integration; nutze für das Add-on weiterhin seinen vorhandenen Ingress-Zugang.</p><p>Die Administratorpflicht des HA-Panels schützt nicht den direkten Zugriff auf einen externen ATLAS-Server. Dessen vorhandene Zugriffsbeschränkung bleibt nötig. Das neue Panel verwendet den Pfad <code>atlas-runtime</code> und ersetzt keinen fremden Seitenleisteneintrag. Das JavaScript-Modul wird unter <code>/atlas_frontend/frontend/atlas-homeassistant-panel.js</code> bereitgestellt; es ist keine zusätzliche Lovelace-Ressource unter <code>/hacsfiles/atlas/</code>.</p><h2 id="geprufter-umfang" tabindex="-1">Geprüfter Umfang <a class="header-anchor" href="#geprufter-umfang" aria-label="Permalink to &quot;Geprüfter Umfang&quot;">​</a></h2><p>Isolierte Prüfungen verwenden Home Assistant Core <strong>2026.10.1</strong>, eine eigene ATLAS-Laufzeit und Testdaten. Konfigurations-/Optionsdialog, Admin-Panel, Neuladen, Neustart, statisches Modul und Erhalt anderer Panels werden geprüft. Einrichtung und Einbettung über HACS sind auf Proxmox/x86_64 und Pi 5/ARM64 geprüft. Der isolierte Integrationswechsel <strong>0.1.301 → 0.1.306</strong>, Rückkehr zu 0.1.301 und erneutes Update erhalten denselben Konfigurationseintrag und die anderen Panels über echte HA-Neustarts. Ein unbekanntes Testformat wird ohne Änderung des Eintrags abgewiesen. Auf Pi 5 und Proxmox ist das HACS-Update auf 0.1.306 samt HA-Neustart, Panel, Live-Entitäten und Datenerhalt geprüft. Die separate ATLAS-App bleibt bei dieser Integrationsprüfung auf 0.1.305.</p><p>Die zusätzliche stabile Version <strong>2026.9.4</strong> ist mit Integration und Laufzeit <strong>0.1.306</strong> in einer frischen isolierten amd64-Installation geprüft: Einrichtung/Optionen, Integrations-Neuladen, vollständiger HA-Neustart, eingebetteter Hub, Administration und Editor, authentifizierte Versionserkennung und Live-Entitätsauswahl. Konfigurationseintrag, andere Panels sowie Testprojekt, Plugin-Daten und Konfigurationsdatei bleiben erhalten. Pi 5 und Proxmox wurden für diese zusätzliche Prüfung nicht verändert. HACS-Download, Supervisor, ARM64 und Integrations-Rollback wurden unter 2026.9.4 nicht erneut geprüft.</p><p>Am <strong>21.10.2026</strong> ist außerdem die genaue Kombination <strong>HA 2026.10.2</strong>, <strong>Integration 0.1.306 / App 0.1.327</strong> auf dem Testklon <strong>.68</strong> geprüft: eingebetteter Hub, Administration und Editor, Live-Verbindung und Entitätssuche, lokales Speichern/Neuladen sowie JSON-/YAML-HACS-Pakete mit je <strong>112/112</strong> und bytegleichem Export/Rückimport/Rückexport. Nach einem echten HA-Core-Neustart verbindet sich der offene Editor ohne Neuladen automatisch wieder. Originaleditor, sieben Serverprojekte, sechs Plugins und erfasste Einstellungen/Dateien sind erhalten; die vorübergehende Runtime-Adresse ist zurückgestellt. <strong>.177 bleibt unverändert und wurde nicht aufgerufen.</strong> Auf .68 bleiben drei Vollbackups. Dies ist kein HA-Update, keine Schemaumwandlung und keine erneute Prüfung einer HACS-Repository-Installation oder von ARM64. Die ursprüngliche Adresse wird in den HA-Optionen ausdrücklich gespeichert; nur Verwaltungszeitstempel ändern sich.</p><p>Die CI-Matrix enthält elf Integrationsverträge je Version für <strong>2026.9.4</strong>, <strong>2026.10.1</strong> und seit dem 21.10.2026 auch <strong>2026.10.2</strong>. Alle drei CI-Zeilen bestehen; die 2026.10.2-Verträge bestehen auch lokal im offiziellen Container ohne Netzwerk. Details und Grenzen stehen in der <a href="https://github.com/rockbaer2007/atlas/blob/main/docs/deployment/HA_COMPATIBILITY_MATRIX.md" target="_blank" rel="noreferrer">Versionsmatrix</a>. Das ersetzt die gesonderten Prüfungen mit laufendem HA nicht und bestätigt keinen durchgehenden Versionsbereich. Weitere HA-Versionen und echte Umwandlungen zwischen unterschiedlichen Datenformaten bleiben separate Qualifikationsschritte.</p><p>Grundlagen: <a href="https://developers.home-assistant.io/docs/frontend/custom-ui/creating-custom-panels/" target="_blank" rel="noreferrer">HA-Custom-Panels</a> und <a href="https://www.hacs.xyz/docs/publish/integration/" target="_blank" rel="noreferrer">HACS-Integrationsstruktur</a>.</p>',37)])])}const p=n(a,[["render",s]]);export{c as __pageData,p as default};
